export const LESSONS={
 guts:{title:'勇气：过保后坚守或撤离',kind:'N5.3 · Guts Roll',source:'https://infinitythewiki.com/Guts_Roll',question:'过保成功，是否就能结束命令？',answer:'承受成功攻击的存活单位还需检查勇气；近战、昏迷和IMM除外。WIP成功坚守，可主动选择失败。Courage可选择自动成功。',positions:[[17,23],[17,19]],overrides:[{},{arm:12,hp:3,maxhp:3}],instructions:'教学提高蓝方护甲与生命：跳过移动 → 蓝方放弃ARO → 红方射击 → 全部过保成功 → 勇气检定。可选择自动失败，查看撤离候选点或俯卧。',dice:[5]},
 flamearo:{title:'喷火反应：射击与模板同时命中',kind:'N5.3 · Direct Template ARO',source:'https://infinitythewiki.com/Direct_Template_Weapons',question:'喷火 ARO 能被射击骰抵消吗？',answer:'不能。喷火自动命中；双方攻击独立结算。主动方可用闪避普通PH检定避开喷火。此例蓝方为专用喷火教学靶机。',positions:[[17,23],[17,19]],overrides:[{hp:3,maxhp:3},{loadout:['heavyFlame'],weapon:'heavyFlame',name:'喷火反应靶机（教学）',trainingWeapon:true}],instructions:'跳过移动 → 蓝方选重型火焰喷射器并确认宣告（此时才显示盖板） → 红方射击或闪避 → 比较结算。',dice:[5]},

 removal:{title:'昏迷后再受伤：移除桌面',kind:'N5.3 · Unconscious / Dead',source:'https://infinitythewiki.com/Dead_State',question:'昏迷模型继续受伤后还留在地图吗？',answer:'普通单位已昏迷后再受伤，进入Dead并移除桌面。遥控存在且STR的单位另有二级昏迷，再多一伤才移除。多伤也可直接超过昏迷阈值；不强制逐次经过每一级。',positions:[[17,23],[17,19]],overrides:[{},{hp:0,states:['unconscious'],prone:true}],instructions:'跳过移动 → 无ARO → 选择蓝方昏迷模型 → 射击 → 过保。确认伤害后，地图移除模型，名册显示已移除。固定骰使一发命中、过保失败。',dice:[10,19,20,20]},
 vision360:{title:'360°目镜：背后也能反应',kind:'N5.3 · 360º Visor',source:'https://infinitythewiki.com/360%C2%BA_Visor',question:'背朝你时，360°目镜能射击吗？',answer:'可以，但仍需几何视线；建筑遮挡不会被目镜忽略。此例蓝方背向红方，教学赋予360°目镜。',positions:[[17,23],[17,19]],overrides:[{},{facing:-90,visor360:true}],instructions:'开始命令 → 跳过移动 → 检查蓝方仍可选择射击。取消命令后关闭蓝方360°开关，可比较普通正面弧。',dice:[8,12,19,9,18]},
 camo:{title:'迷彩：延后 ARO 与揭露',kind:'N5.3 · Camouflage',source:'https://infinitythewiki.com/Camouflage',question:'看到迷彩移动，能等它攻击后再反应吗？',answer:'可以延后。第二项技能揭露则可宣告ARO；若仍是标记，延后者失去本命令ARO，不能再补发现。',positions:[[17,23],[17,19]],overrides:[{camouflage:true,states:['camouflaged'],mim:3,surpriseAttack:3},{}],instructions:'跳过移动 → 蓝方选择延后 → 红方攻击（揭露）或第二技能待机（不揭露），比较新增ARO。此例技能是教学覆写。',dice:[8,12,19,9,18]},
 discover:{title:'发现：先发现再射击',kind:'N5.3 · Discover',source:'https://infinitythewiki.com/Discover',question:'能直接射击迷彩标记吗？',answer:'通常不能。先宣告发现、再宣告攻击；结算先检定发现，失败则原定攻击无效。同一观察者本玩家回合失败后不能重试同一标记。',first:'discover',positions:[[17,23],[17,19]],overrides:[{},{camouflage:true,states:['camouflaged'],mim:3}],instructions:'开始发现 → 蓝方待机 → 选择蓝方为射击目标 → 先掷WIP发现，再掷攻击骰。重置并关闭固定骰可体验失败分支。',dice:[7,8,12,19,18]},
 sensor:{title:'传感器：隔墙搜索标记',kind:'N5.3 · Sensor',source:'https://infinitythewiki.com/Sensor',question:'Sensor 是否受拟态和墙阻挡？',answer:'Sensor 短技能用 WIP+6，一次检定揭露8英寸控制区内的迷彩及隐匿部署；不需要视线，不受拟态修正。普通发现也获得Sensor的+6。',positions:[[17,23],[20,24]],overrides:[{sensor:true},{camouflage:true,states:['camouflaged'],mim:6}],instructions:'跳过移动 → 对面待机 → 点击Sensor → 完成ARO → 掷技能骰。此例为技能教学覆写。',dice:[8,18]},
 modifiers:{title:'拟态与 BS Attack(−3)',kind:'N5.3 · Skills and MODs',source:'https://infinitythewiki.com/Skills_and_Equipment_in_Infinity',question:'拟态−3 与 BS Attack(−3) 相同吗？',answer:'拟态作用于需要视线的敌方BS攻击和发现；BS Attack(−3)只在持有者使用该技能的拼骰中施加。蓝方待机时不会施加其BS Attack(−3)。',positions:[[17,23],[17,19]],overrides:[{},{mim:3,bsAttackNegative:-3}],instructions:'待机 → 蓝方选择射击 → 红方射击，查看双方面板SV；重置后让蓝方待机比较。多光谱可减免拟态，不消除BS Attack(−3)。',dice:[8,12,19,9,18]},
 console:{title:'Hardlock：激活控制台',kind:'ITS18 · Scenario',source:'https://experience.corvusbelli.com/en/game-content/4fdeacaa-ad46-4d37-aa5b-d5284f452653',question:'谁可以激活控制台？',answer:'专家本人接触控制台，花费一个短技能进行普通WIP检定；成功将控制台转为己方。无Uplink的连续失败加成。',positions:[[12,24+20/25.4+12.5/25.4],[45,34]],overrides:[{specialist:true},{}],instructions:'跳过移动 → 确认ARO → 目标选西控制台 → 激活控制台 → 检定并确认。观察控制台颜色及预估得分。此例战士教学赋予专家。',dice:[7,18]},
 saves:{title:'过保：双重弹药与昏迷',kind:'N5.3 · Saving Roll / DA',source:'https://infinitythewiki.com/Saving_Roll',question:'拼骰成功以后是否直接扣血？',answer:'先确定未抵消的命中，再计算过保次数与属性。此例训练器使用 B1 / PS8 / DA：普通命中两次 ARM 过保，暴击再加一次。',positions:[[17,23],[17,19]],weapon:'lab',modeId:'DA',instructions:'跳过移动 → 敌人放弃 ARO → 选择目标 → 拼骰 → 核对过保次数 → 掷过保 → 确认伤害。固定骰让一颗过保失败，VITA1 进入昏迷。',dice:[10,20,3]},
 em:{title:'E/M：孤立与不可移动 B',kind:'N5.3 · E/M / Isolated',source:'https://infinitythewiki.com/Electromagnetic_(E/M)_Ammunition',question:'E/M 会把机甲打掉血吗？',answer:'纯 E/M 不造成伤口。每次命中两次半 BTS（向上取整）过保；失败施加孤立，HI / TAG / REM / VH 还进入不可移动 B。',positions:[[17,23],[17,19]],overrides:[{},{name:'TAG 状态教具',en:'TAG TEST',s:7,slug:'guijia-squadrons',type:'TAG',attribute:'STR',bts:6,maxhp:3,hp:3}],weapon:'lab',modeId:'EM',instructions:'待机 → 对面放弃 ARO → 选择目标 → 分阶段结算。看角色旁的状态；结束当前回合后，孤立单位用自身不规则命令 Reset−12 尝试解除。',dice:[10,20,4,1]},
 para:{title:'PARA：PH 过保与不可移动 A',kind:'N5.3 · PARA',source:'https://infinitythewiki.com/Paralysis_(PARA)_Ammunition',question:'麻痹弹是 ARM 或 BTS 过保吗？',answer:'不是。PARA 用 PH−6；失败进入不可移动 A，不损失生命。只能 Dodge−6，成功解除后可以闪避移动。',positions:[[17,23],[17,19]],weapon:'lab',modeId:'PARA',instructions:'待机 → 对面放弃 → 选目标 → 结算。可切到对面回合尝试闪避解除。',dice:[10,18,2]},
 lowwall:{title:'矮墙：0.7″ 与 1.7″',kind:'N5.3 · Cover / Silhouettes',source:'https://infinitythewiki.com/Cover',question:'低于 S1 的墙能给 S2 掩体吗？',answer:'可以，前提是接触并遮住部分轮廓；没有必须遮住三分之一的要求。0.7 英寸低于 S1，1.7 英寸略高于 S2，后者可完全挡住地面 S2。',positions:[[30,24],[30,29.6+25/25.4/2]],overrides:[{facing:90},{facing:-90}],instructions:'当前目标贴着地图上的 0.7″ 墙。点击切换墙高，比较 0.7″ 部分掩体和 1.7″ 完全遮挡；默认地图另有 1.7″ 墙位于 (17,16)。',dice:[10,20,3]},

 room:{title:'任务房间：无限高围墙与入口',kind:'ITS18 · 特殊地形示意（非任务复刻）',source:'https://experience.corvusbelli.com/en/infinity/its',question:'无限高房间是不是不可进入的实心方块？',answer:'不是。此例为中空房间、无限高围墙及四个 3 英寸开放入口；内部可进入。门宽为沙盘教学参数，正式 ITS 任务应按该任务门规格。无限高不是普通建筑通用属性。',positions:[[24,29,0],[24,18,0]],route:[{x:24,y:29,z:0},{x:24,y:26,z:0}],instructions:'应用示例路线穿过南门进入内部，再用视线剖面对比穿门与穿墙。此例只演示地形，不替代当前任务计分。',dice:[12,8,19]},

 height:{title:'楼高：地面与屋顶视线',kind:'N5.3 · Silhouettes / Line of Fire',source:'https://infinitythewiki.com/Line_of_Fire',question:'S7 机甲能直接越过 4 英寸楼房看到地面敌人吗？',answer:'S7 轮廓高 67 mm，约 2.64 英寸；不能因为是机甲就看穿楼。切换屋顶观察点，查看脚底高度改变后的三维视线。',positions:[[8,14,0],[8,2,0]],overrides:[{s:7,name:'龟甲（高度教具）',slug:'guijia-squadrons',en:'GUIJIA',facing:-90},{facing:90}],instructions:'使用“切换地面／屋顶观察点”，观察下方视线剖面。此按钮重设教学位置，不是一次游戏内移动。',dice:[12,8,19]},
 climb:{title:'攀爬：从墙边到 4″ 屋顶',kind:'N5.3 · Climb / Climbing Plus',source:'https://infinitythewiki.com/Climb',question:'普通单位能上楼吗？',answer:'可以。普通 Climb 是长技能，MOV 第一值＋2 英寸，需先接触墙。强化攀爬可将第一项 Climb 变成基本短技能；完整底座到达屋顶后停止。',positions:[[5-25/25.4/2,8,0],[17,19,0]],first:'climb',instructions:'开始命令 → 点击相接触的 01 / STORAGE 楼房 → 自动规划登顶 → 确认。可在单位教学属性开启强化攀爬，再重试基本短技能版本。',dice:[12,19,20]},
 jump:{title:'超级跳：屋顶跨越',kind:'N5.3 · Super-Jump',source:'https://infinitythewiki.com/Super-Jump',question:'超级跳为什么可以跳跃后射击？',answer:'拥有该技能时，首项 Jump 可作为基本短技能，随后可射击。短跳为 MOV1＋2 英寸，整令跳为 MOV1＋4；必须有完整水平落点，不能自由坠落。',positions:[[8,8,4],[17,19,0]],first:'superjump',overrides:[{superJump:true},{}],instructions:'开始命令 → 直接点击同一屋顶内的终点。系统自动识别高度并规划直线分段路线；长跳和短跳的预算不同。',dice:[12,19,20]},
 fireteam:{title:'火力组：额外骰与弃骰',kind:'N5.3 · Fireteam Bonuses',source:'https://infinitythewiki.com/Fireteam_Bonuses',question:'L2 火力组的 +1 SD 等于多一发射击吗？',answer:'不等于。B3 掷 4 骰后弃 1；反应 B1 掷 2 骰后弃 1。双方掷完后主动方先弃。本例仅演示奖励，不模拟完整火力组激活。',positions:[[17,23],[17,19]],overrides:[{ftLevel:2},{ftLevel:2}],instructions:'待机 → 敌人复合步枪反应 → 主动方复合步枪攻击 → 掷骰。主动方先点选弃骰，再由反应方弃骰，然后查看抵消和过保。',dice:[3,12,17,20,8,14,19]},

 cc:{title:'近战：移动到接触',kind:'N5.3 现行规则例',source:'https://infinitythewiki.com/CC_Attack',question:'移动路线碰到敌方底座后，还能继续穿过去吗？',answer:'不能。移动在轮廓接触处结束；之后可用近战武器，以 CC 属性对抗敌方反应。',positions:[[17,23],[17,21]],route:[{x:17,y:23},{x:17,y:21+25/25.4}],instructions:'开始命令 → 应用示例路线 → 确认移动 → 敌方选择近战武器 → 主动方选择近战 → 选择近战武器并点敌人 → 结算。',dice:[12,9,18]},
 dodge:{title:'闪避：避开喷火后移动',kind:'N5.3 现行规则例图',source:'https://infinitythewiki.com/Dodge',question:'面对自动命中的直射模板，闪避需要与攻击骰对抗吗？',answer:'不需要；普通 PH 掷骰成功即可避开模板，并可选择最多 2 英寸移动。无视线时通常有 PH−3 修正。',positions:[[17,23],[17,19]],instructions:'开始命令 → 跳过移动 → 敌方选择闪避 → 主动方选择射击 → 选择轻型火焰喷射器并点敌人 → 结算 → 点击闪避终点。',dice:[5]},
 prone:{title:'FAQ：终点俯卧与移动距离',kind:'FAQ V0.1 · p.1 / Movement Module',source:'https://infinitythewiki.com/General_Movement_Rules#FAQs',question:'在移动结束时进入俯卧，会减少本次可移动距离吗？',answer:'不会。终点才俯卧仍可走完正常距离；若在起点俯卧并沿途爬行，则本次移动距离减半。俯卧高度按 3 mm 参与本版视线近似。',positions:[[17,23],[45,45]],route:[{x:17,y:23},{x:17,y:27}],instructions:'开始命令 → 选择“终点俯卧” → 应用 4″ 示例路线 → 确认。重置后改为“起点俯卧”，同一路线会因超过 2″ 被拒绝。',dice:[5]},
 position:{title:'FAQ：何时选择目标所在点',kind:'FAQ V0.1 · p.1 / Basic Rules',source:'https://infinitythewiki.com/Order_Expenditure_Sequence#FAQs',question:'宣告射击时，是否必须马上选定移动目标在路径上的哪个位置？',answer:'FAQ 的例外是目标所在位置：在结算阶段、测量射程之前选择。武器、模式、射击者位置等其他细节仍在宣告时确定。',positions:[[17,23],[17,11]],route:[{x:17,y:23},{x:17,y:27}],instructions:'移动 4″ → 敌人宣告复合步枪 → 主动方射击或待机 → 在结算面板选择敌人瞄准路径上的位置，再掷骰。宣告前不显示射程与覆盖；确认后按步骤检查。',dice:[12,19,20,9,18]}
};

LESSONS.hacking={title:'黑客：聚光与 Reset',kind:'N5.3 黑客教学（独立训练配置）',source:'https://infinitythewiki.com/Spotlight',question:'黑客攻击需要视线吗？',answer:'自身黑客控制区内的程序不需要视线；Spotlight 使用 WIP，目标以 Reset 对抗，再进行 BTS 过保。',instructions:'开始命令 → 跳过移动 → 对方选择 Reset → 主动方黑客 → 选择程序及目标 → 结算。',positions:[[17,23],[21,23]],dice:[10,8,17],overrides:[{name:'黑客训练员（教学）',hackingDevice:'HD',wip:13},{type:'REM',attribute:'STR',bts:3}]};
LESSONS.doctor={title:'医生：救治与失败重掷',kind:'N5.3 · Doctor',source:'https://infinitythewiki.com/Doctor',question:'医生能在反应轮救人吗？',answer:'不能。医生为主动轮短技能；接触昏迷 VITA 目标进行普通 WIP 检定，成功恢复，最终失败移除。目标有 Cube 可花指挥令重掷。',instructions:'开始命令 → 跳过移动 → 医生 → 救治伤员 → 宣告 → 掷 WIP；失败时可选择指挥令重掷。红方医生为明确教学覆写。',positions:[[17,23],[17,23+25/25.4]],overrides:[{doctor:{rerollWip:12},name:'医生训练员（教学）'},{team:0,name:'昏迷伤员（教学）',hp:0,states:['unconscious'],prone:true,cube:true}],dice:[20,7]};
LESSONS.engineer={title:'工程师：昏迷 II 与状态修复',kind:'N5.3 · Engineer',source:'https://infinitythewiki.com/Engineer',question:'工程师一次成功能恢复遥控存在的二级昏迷吗？',answer:'可以，一次成功恢复至 1 STR。解除状态另选模式；修复失败加 1 伤，解除状态失败不造成伤害。',instructions:'跳过移动 → 工程师 → 选择修复损伤或解除状态 → 掷 WIP。此例为教学覆写的遥控存在靶机。',positions:[[17,23],[17,23+25/25.4]],overrides:[{engineer:true,name:'工程师训练员（教学）'},{team:0,name:'遥控机伤员（教学）',type:'REM',attribute:'STR',remotePresence:true,hp:-1,states:['unconscious2','isolated','immB'],prone:true}],dice:[7]};
LESSONS.deployable={title:'部署物：放置、触发与装填',kind:'N5.3 · Place Deployable',source:'https://infinitythewiki.com/Place_Deployable',question:'刚放下的地雷能马上触发吗？',answer:'不能，命令结束才放置生效。部署时消耗使用次数；之后的命令中才检查触发。反应轮放置还必须看见主动单位。',instructions:'跳过移动 → 放置部署物 → 点击本人底盘旁的水平位置 → 宣告。完成后结束回合，让敌人移动接近地雷。教学提供地雷、中继器和友方辎重。',positions:[[17,23],[17,12]],overrides:[{name:'部署物训练员（教学）'},{}],equipment:{a0:{deployableItems:['shockMine','deployableRepeater']}},extras:[{name:'辎重支援（教学）',en:'BAGGAGE',team:0,x:21,y:23,baggage:true}],dice:[5,20]};
LESSONS.reload={title:'装填：主动轮与 ARO 补给',kind:'N5.3 · Reload',source:'https://infinitythewiki.com/Reload',question:'没有看到敌人也能装填 ARO 吗？',answer:'先要有合法 ARO 机会；Reload 不额外要求视线。装填者须在有效友方辎重的控制区内，每条命令每方只能让一个单位补充。',instructions:'红方跳过移动 → 蓝方可选装填 ARO → 红方选装填 → 无骰完成补给。双方均为显式装备教学配置；状态阶段也会自动补充。',positions:[[17,23],[17,19]],equipment:{a0:{loadout:['panzerfaust','pistol','cc'],weapon:'panzerfaust',spentWeapons:{panzerfaust:2}},b0:{loadout:['panzerfaust','pistol','cc'],weapon:'panzerfaust',spentWeapons:{panzerfaust:1}}},extras:[{name:'红方辎重（教学）',team:0,x:21,y:23,baggage:true},{name:'蓝方辎重（教学）',team:1,x:21,y:19,baggage:true}],dice:[5]};

LESSONS.smoke={title:'烟雾／Eclipse：拼骰与视线',kind:'N5.3 · 专用教学装备',source:'https://infinitythewiki.com/Smoke_Ammunition',question:'烟雾与迪斯科球能用来抵消枪击吗？',answer:'烟雾／Eclipse 仅对穿过拟生成区域、需要掷骰且需要视线的来袭攻击拼骰。普通烟雾不与 MSV 拼骰；Eclipse 可以。迪斯科球始终普通检定。',positions:[[17,23],[17,17]],equipment:{a0:{loadout:['combi','smokeGrenade','eclipseGrenade'],ph:13,name:'烟雾投掷手（教学）'},b0:{loadout:['combi','smokeGrenade'],name:'烟雾反应手（教学）'}},instructions:'待机 → 蓝方射击 → 红方投掷／发射部署武器 → 选择烟雾 → 点击两人之间 (17,21) → 确认后展示待定圆模板 → 拼骰。也可让蓝方使用烟雾 ARO。结束回合清除烟区。',dice:[10,6]};
LESSONS.disco={title:'迪斯科球：投射、失活、重新激活',kind:'N5.3 · 专用教学装备',source:'https://infinitythewiki.com/Disco_Baller',question:'球产生的 Eclipse 何时生效？',answer:'投射是普通 BS 检定；成功后命令结束才放球和 Eclipse。状态阶段区域消失，球仍在。持 Deactivator 者可用主动短技能重新激活友方球。',positions:[[17,23],[17,17]],equipment:{a0:{loadout:['combi','discoBaller'],deactivator:true,name:'迪斯科球操作员（教学）'},b0:{loadout:['combi','discoBaller'],deactivator:true,name:'迪斯科反应手（教学）'}},instructions:'待机 → 蓝方放弃或射击 → 红方投射迪斯科球至 (17,21) → 检定 → 命令结束出现球及紫色区域。结束双方回合后可选激活迪斯科球。Double Shot 消耗两发；重叠球需在结束时另选合法位置。',dice:[7,5]};
LESSONS.rangedDeploy={title:'部署武器：投掷地雷／中继器',kind:'N5.3 · 专用教学装备',source:'https://infinitythewiki.com/Drop_Bears',question:'投掷与贴身放置是否共享使用次数？',answer:'Drop Bears 两种模式共享三次；投掷需要 PH 检定，贴身放置无需检定。所有 Targetless／放置 ARO 必须看到主动单位；新部署物不会在本命令触发。',positions:[[17,23],[17,17]],equipment:{a0:{loadout:['combi','dropBears','pitcher','mineDispenser'],deployableItems:['apMine','emMine','paraMine','monoMine','viralMine'],name:'部署武器操作员（教学）'},b0:{loadout:['combi','dropBears','pitcher'],name:'部署武器反应手（教学）'}},instructions:'普通命令先待机，再选择放置部署物或投掷／发射。整令推测射击从第一行动选择，无第二技能；直觉放置地雷可处理只有敌方迷彩的触发区。投射点可选 (18,20)。',dice:[7]};
LESSONS.whiteNoise={title:'白噪声：阻挡 MSV 与 Marksmanship',kind:'N5.3 · 专用教学装备',source:'https://infinitythewiki.com/White_Noise',question:'白噪声与普通烟雾有何不同？',answer:'白噪声只阻挡 MSV 或 Marksmanship。需要具备 White Noise 程序，仅主动短技能；整圆必须在黑客区域内。WIP 成功后命令结束生效，施术者暂停拟态等 NFB 能力。',positions:[[17,23],[17,17]],equipment:{a0:{loadout:['combi'],hackingDevice:'HDPlus',mim:3,name:'白噪声黑客（教学）'},b0:{loadout:['combi'],msv:2,name:'MSV2 观察员（教学）'}},instructions:'待机 → 蓝方放弃 → 第二项行动白噪声 → 指定 (17,21) → WIP 检定。完成后查看视线；白噪声不能抵消本次枪击，状态阶段清除。',dice:[7]};
LESSONS.tagcom={title:'军表实装：TAGCom 支援炽天使',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/TAGCom',question:'支援修正是否受距离和主动／反应轮限制？',answer:'同战斗组的在场非空状态 TAGCom 提供者，给予 TAG 闪避 PH+3、接受维修包 PH+1；不叠加。此例使用原 MO 军表的炽天使与 Tech-Bee。',armyProfiles:[34,935],positions:[[17,23],[17,23+40/25.4]],instructions:'炽天使选择闪避 → 完成命令，核对 专属闪避 PH12+3=15。也可选 Tech-Bee 使用维修包救治受损炽天使，专属维修包 PH13+1=14。部署、伤口与坐标为演练设置，武器技能来自军表。',overrides:[{hp:2},{}],dice:[12]};

LESSONS.blitzen={title:'军表实装：Blitzen 主动／反应射击',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/Weapon_Chart',question:'反应轮能使用 Blitzen 吗？',answer:'可以，需要视线。两发共用库存，宣告即扣除；命中每发两次半 BTS 过保，失败造成孤立，重步兵等另有不可移动 B，不扣生命。双方使用军表中的 Montesa FTO。',armyProfiles:[28,28],positions:[[17,23],[17,19]],overrides:[{}, {team:1,facing:90}],instructions:'待机 → 蓝方 Blitzen ARO → 红方射击选择 Blitzen → 结算；观察弹药从2到1、BTS过保及状态。',dice:[10,9,20,20]};

LESSONS.possession={title:'军表实装：全面控制炽天使',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/Total_Control',question:'全面控制成功后谁能使用 TAG？',answer:'过保失败后改用黑客阵营和战斗组命令；MOV4-4、CC13、BS12、WIP11，不产生命令。原拥有者下回合战术阶段可用一枚指挥令解除。',armyProfiles:[24,34],positions:[[17,23],[21,23]],overrides:[{}, {team:1,facing:180}],instructions:'待机 → 炽天使 Reset → 黑客选择全面控制 → 比较与两次 BTS 过保。成功后检查名册阵营和属性；结束回合在原拥有者战术阶段解除。',dice:[8,19,20,20]};

LESSONS.suppressive={title:'军表实装：进入压制射击',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/Suppressive_Fire_State',question:'压制射击可以作为第二短技能吗？',answer:'不可以；进入状态需要主动整令。以后只用选定模式 ARO，B3、最多24英寸；24英寸内对抗对手−3。改用其他反应或败勇气会取消。',armyProfiles:[24,24],positions:[[17,23],[17,19]],overrides:[{}, {team:1,facing:90}],first:'suppressive',instructions:'选择复合步枪压制模式 → 开始整令 → 对方放弃 ARO → 无骰进入状态。结束回合，蓝方待机，红方选择压制射击 ARO；核对 B3 和对手−3。',dice:[10,8,7,6]};

LESSONS.cybermine={title:'军表实装：电子地雷与 Reset',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/Mines',question:'闪避能避开电子地雷吗？',answer:'不能。必须 Reset WIP−3。命中后两次 BTS 过保，PS5；可黑或黑客进入不可移动B，其他单位眩晕，不扣生命。',armyProfiles:[1588,30],positions:[[17,23],[17,19]],overrides:[{}, {team:1,facing:90}],instructions:'鸦眼待机 → 对面放弃 → 放置电子地雷于本人北侧接触点 → 完成命令。结束回合，条顿骑士待机触雷，第二技能选择 Reset 或 Dodge 比较。',dice:[20,20,20]};

LESSONS.turret={title:'军表实装：武装炮塔',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/Armed_Turret',question:'炮塔是否必须贴身放置？',answer:'不需要，Perimeter 允许完整位于8寸控制区内的可达位置。它仅对主动敌方模型射击或近战 ARO；不能行动、闪避、重置或攻击迷彩。',armyProfiles:[1587,24],positions:[[17,23],[17,19]],overrides:[{}, {team:1,facing:90}],instructions:'监护使待机 → 对方放弃 → 放置武装炮塔至 (20,23) → 结束命令。结束回合，蓝方待机，检查炮塔只有射击／近战和放弃选项，射手步枪 ARO B3。',dice:[8,9,10,20]};

LESSONS.controlledJump={title:'军表实装：EVO 干扰战斗空降',kind:'N5.3 · 两份军表真实配置',source:'https://infinitythewiki.com/Controlled_Jump',question:'EVO 看不到空降兵也能反应吗？',answer:'敌方宣告战斗空降时，全场 EVO 可在 PH 检定之前宣告跳跃控制，立即使敌方 PH−3；之后不能再宣告落地 ARO。',armyProfiles:[[201,126],38],positions:[[17,43],[40,5]],overrides:[{offTable:true,airborneOrderAvailable:true},{team:1}],instructions:'虎战士选择战斗空降 → 点击合法落点 → 点击确认，先出现全场 EVO 选择 → 骡式遥控机宣告跳跃控制 → 再掷 PH。',dice:[10]};

LESSONS.demolition={title:'军表实装：爆破装药',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/D-Charges',question:'爆破模式与近战模式能分别使用三次吗？',answer:'不能，共享三次。爆破只能主动短技能，接触 IMM／Null 敌人自动命中；近战模式主动／ARO 均可，CC−6。',armyProfiles:[1587,30],positions:[[17,23],[17,23-25/25.4]],overrides:[{}, {team:1,facing:90,states:['immB']}],instructions:'监护使待机 → 条顿 Reset → 选择爆破装药并指定条顿 → 自动命中后三次 ARM/2 过保。处于IMM的教学状态不更改单位装备配置。',dice:[20,20,20,20]};

LESSONS.terrain={title:'军表实装：山地与普通移动',kind:'N5.3 · 两份军表真实配置',source:'https://infinitythewiki.com/Terrain',question:'Terrain 是否永远增加移动？',answer:'只有在匹配区域宣告移动时，第一 MOV+1；无匹配技能进入困难区域须停止本命令移动，下令在区域中移动−1。多地形配置在部署时选一种，Total适用全部类型。',armyProfiles:[[201,1841],30],positions:[[17,23],[17,19]],overrides:[{}, {team:1,facing:90}],terrainAreas:[{x:15,y:20,w:5,h:10,type:'Mountain'}],instructions:'孤胆在绿色山地区域开始移动，核对 MOV1+1。条顿仅擅长丛林，从外进入山地会停在边缘，不能接着走第二段。',dice:[10]};

LESSONS.holomask={title:'军表实装：全息伪装',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/HoloMask_State',question:'伪装成黑客能获得黑客程序吗？',answer:'不能。外观只改变模型身份，判定始终使用真实配置。它仍是模型，可直接射击或发现，不提供迷彩延后 ARO。重新进入仅主动整令，需在敌方视线之外。',armyProfiles:[1561,24],positions:[[17,23],[45,45]],overrides:[{}, {team:1,facing:90}],first:'remask',instructions:'选择同分军同S的外观 → 全息伪装整令 → 完成结算 → 检查名册和真实武器。再宣告需掷骰的技能，全息外观取消。部署阶段也可直接选择该状态。',dice:[10]};

LESSONS.guided={title:'军表实装：炽天使 ECM 制导−6',kind:'N5.3 · 敌方为明确标注的制导教学靶机',source:'https://infinitythewiki.com/BS_Attack',question:'ECM 需要声明 ARO 吗？',answer:'不需要，它自动影响针对持有者的制导攻击。制导必须自带技能、只限主动轮，对被标记目标可无视视线；B1，保留射程修正、忽略一般负修正，目标可闪避或重置对抗。',positions:[[17,23],[17,19]],armyProfiles:[19,34],overrides:[{team:0,name:'制导教学靶机（非军表配置）',guided:true,loadout:['guidedTraining'],weapon:'guidedTraining',armyWeapons:{},trainingWeapon:true},{team:1,states:['targeted'],facing:-90}],instructions:'待机 → 炽天使宣告 Reset → 主动方选择制导导弹 → 核对 BS8−3射程+3标记−6ECM=2，对抗 WIP13−3=10。正式军表不会凭空获得制导技能。',dice:[4,3]};

LESSONS.evoSupport={title:'军表实装：EVO 支援程序',kind:'N5.3 · 原军表真实配置',source:'https://infinitythewiki.com/Supportware',question:'辅助射击和强化反应能作为 ARO 吗？',answer:'不能，它们和仙尘都是主动整令。跳跃控制允许主动短技能／合法 ARO，战斗空降另有全场反应窗口。同一黑客一次维持一个支援程序。',armyProfiles:[38,19],positions:[[17,23],[17,19]],first:'program:assistedFire',instructions:'选择辅助射击／强化反应／仙尘整令，指定友方单位或类型，结算不掷骰。在单位面板检查 Marksmanship、ARO B2 或 Firewall−3；新程序替换旧程序。',dice:[10]};

LESSONS.demolitionCC={...LESSONS.demolition,title:'军表实装：爆破装药近战模式',overrides:[{}, {team:1,facing:90}],instructions:'监护使待机 → 条顿近战 ARO → 监护使选择近战及爆破装药（CC−6）。近战可主动或 ARO；爆破自动命中模式只能主动使用。'};

LESSONS.fireteam30={title:'真实军表：Core 全组行动与 ARO',kind:'N5.3 / FAQ0.1 · MO 原始配置',source:'https://infinitythewiki.com/Fireteams_in_the_Active_Turn',question:'五个人是否必定是等级5？',answer:'不是。本例持杖廷卫、骑士指挥官和FTO军士同算Crosier，共3同源；另外两人不算同源，所以5人Core是L3。只花一条命令，全员依次移动后才进入ARO；攻击只有队长执行。',armyProfiles:[1560,1561,24,771,1587,[201,139]],positions:[[17,23],[15.6,24.6],[16.9,25.9],[19.5,23.3],[19.5,22],[17,18]],overrides:[{team:0},{team:0},{team:0},{team:0},{team:0},{team:1,facing:90}],first:'move',instructions:'队长移动 → 其余4人逐个移动或0寸 → 蓝方选一个激活成员反应 → 第二项再移动或仅队长射击 → 新增ARO → 同时结算。命令末检查一致性。结束回合后蓝方行动，红组各成员独立宣ARO；异类ARO即时脱组并重算等级。',dice:[3,12,17,8,14,19]};

LESSONS.jetJump34={title:'炽天使：9寸喷气超级跳',kind:'N5.3 · 真实配置 / Super-Jump (+3, Jet Propulsion)',source:'https://infinitythewiki.com/Super-Jump',question:'MOV6、超级跳+3为何只能跳8寸？喷气推进能否空中转向？',answer:'短超级跳预算应为6+3=9寸；整令超级跳仍为6+4=10寸。喷气推进可在空中改变方向，普通跳跃不能改变水平前进方向。按三维直线分段计距，不强制生成抛物线。跳跃接触落地表面即结束，之后另选第二项Move，使用MOV2。',armyProfiles:[34,[201,139]],positions:[[8,11+55/50.8],[17,19]],overrides:[{team:0},{team:1,facing:90}],first:'superjump',route:[{x:8,y:11+55/50.8,z:0},{x:8,y:11+55/50.8,z:4},{x:8,y:6+55/50.8,z:4}],instructions:'开始短超级跳 → 可直接点击4寸楼顶落点；或点击“在当前途经点垂直升降”上升4寸，再指定最终落点。应用示例路线可验证4寸上升+5寸水平共9寸。要空中转向，选择添加空中途经点，最后切回最终落点。确认完整轨迹后宣告ARO。',dice:[12,8,19]};

// N5.3 regression scenes use declared fixtures; no hidden test-state mutations.
for(const kind of ['smoke','eclipse'])LESSONS[kind+'CC']={title:(kind==='smoke'?'烟雾':'迪斯科球 Eclipse')+'：接触后近战',kind:'FAQ · N5.3 / Engaged',source:'https://infinitythewiki.com/Line_of_Fire',question:'零能见度区域里，轮廓接触后能否近战？',answer:'可以。近战不要求区域外视线；接触双方不受能见度条件影响。区域仍阻挡远处射击，实体墙仍阻止接触。',positions:[[17,23],[17,21]],terrain:[],zones:[{id:'lesson-zone',kind,x:17,y:22,r:2.75,z:0}],route:[{x:17,y:23,z:0},{x:17,y:21+25/25.4,z:0}],instructions:'开始命令 → 应用示例路线 → 确认移动 → 蓝方近战 ARO → 主动方近战并选择蓝方 → 结算。双方不应出现能见度 −6 或无视线惩罚。',dice:[12,9,18]};
LESSONS.narrowPassage={title:'窄通道：25 mm 底盘通过 12.5 mm',kind:'N5.3 · Move / 移动与地形',source:'https://infinitythewiki.com/Move',question:'通道内的途经点和本段移动终点一样吗？',answer:'不一样。通道至少半个底盘宽即可经过，但本段移动必须结束在可容纳完整底盘的位置。不能在窄道中结束第一段，再靠第二段走出去。',positions:[[17,23],[30,29]],terrain:[{id:'narrow-left',name:'12.5 mm PASSAGE / LEFT',kind:'building',x:13,y:20,w:4-12.5/25.4/2,h:2,height:4},{id:'narrow-right',name:'12.5 mm PASSAGE / RIGHT',kind:'building',x:17+12.5/25.4/2,y:20,w:4,h:2,height:4}],route:[{x:17,y:23,z:0},{x:17,y:21.4,z:0},{x:17,y:19.3,z:0}],instructions:'开始移动 → 在窄道中心 (17,21.4) 点击添加途经点 → 尝试确认，应提示终点重叠 → 点击出口 (17,19.3) → 确认移动成功。也可应用示例路线。',dice:[12]};

LESSONS.roofARO={title:'楼顶 Z 轴：近墙与退后',kind:'N5.3 · Line of Fire / 移动与地形',source:'https://infinitythewiki.com/Line_of_Fire',question:'楼上单位的视线是否从底盘中心发出？',answer:'不是。视线可以从整个轮廓任一点发出，目标要有至少3×3 mm可见部分。贴近屋顶边缘可看向墙脚；退后会被屋顶遮挡。地图反应线是俯视投影，剖面保留实际Z高度。',positions:[[4.4,5],[5+25/50.8,5,4]],overrides:[{facing:0},{facing:180}],terrain:[{id:'roof-los',name:'ROOF / 4 INCH',kind:'building',x:5,y:2,w:7,h:6,height:4}],route:[{x:4.4,y:5,z:0},{x:4.4,y:7,z:0}],instructions:'先检查蓝方屋顶到红方墙脚的视线；选择蓝方作为视线观察者。红方移动后，蓝方可宣告复合步枪ARO；结算目标点显示Z高度。使用教学属性修改位置退后时，应重新被屋顶遮挡。',dice:[12,9,18]};
